//! The integration API against upstream's own router and dispatcher (RIIR 5).
//!
//! `fixtures/integration.json` is generated by scripts/upstream-oracle/
//! gen-integration.ts: each request went through upstream's Express router and
//! `dispatchFromAdapter`, with the services replaced by recorders, and the
//! fixture holds which service call it became, or the error it was refused
//! with. Here the same request goes through our `http_call` and `parse`, and
//! the action it parses to is described as the call upstream would have made.

use ontime_core::aux_timer::{AuxCommand, SimpleDirection};
use ontime_core::command::Command;
use ontime_core::integration::{
    change_patch, http_call, parse, Action, ClientCommand, HttpCall, IntegrationError,
};
use ontime_core::project::Project;
use ontime_core::rundown::Rundown;
use serde::Deserialize;
use serde_json::{json, Map, Value};

#[derive(Deserialize)]
struct HttpCase {
    name: String,
    path: String,
    ok: bool,
    status: u16,
    body: Value,
    calls: Vec<Value>,
}

#[derive(Deserialize)]
struct WsCase {
    name: String,
    tag: String,
    /// Absent is `undefined`; a JSON `null` is a payload of null.
    #[serde(default, deserialize_with = "present")]
    payload: Option<Value>,
    ok: bool,
    error: Option<String>,
    calls: Vec<Value>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Cases {
    rundown: Value,
    custom_fields: Value,
    http: Vec<HttpCase>,
    ws: Vec<WsCase>,
}

#[derive(Deserialize)]
struct Fixture {
    cases: Cases,
}

fn present<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<Option<Value>, D::Error> {
    Value::deserialize(deserializer).map(Some)
}

/// Upstream's results this fork deliberately does not follow, with why.
const DELIBERATE: &[(&str, &str)] = &[
    (
        "start ignores the room token",
        "a Worker room is reached with ?token=, which upstream (on a LAN) has no use \
         for; it is the host's, so it is taken off before the query becomes a payload",
    ),
    (
        "addtime as a fraction",
        "the runtime counts whole milliseconds, so 1500.4 is added as 1500; upstream \
         carries the fraction into every timer value after it",
    ),
];

/// Numbers compared by value: upstream's 120 and our 120.0 are the same.
fn normalised(value: &Value) -> Value {
    match value {
        Value::Number(n) => match n.as_f64() {
            Some(f) if f.fract() == 0.0 && f.abs() < 9e15 => json!(f as i64),
            _ => value.clone(),
        },
        Value::Array(items) => Value::Array(items.iter().map(normalised).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, v)| (k.clone(), normalised(v)))
                .collect(),
        ),
        other => other.clone(),
    }
}

fn fixture() -> Cases {
    let fixture: Fixture = serde_json::from_str(include_str!("fixtures/integration.json")).unwrap();
    fixture.cases
}

/// A project whose loaded rundown holds the fixture's entries.
fn project(cases: &Cases) -> Project {
    let mut project = Project {
        custom_fields: cases.custom_fields.clone(),
        ..Default::default()
    };
    let entries = cases.rundown["entries"].as_object().unwrap();
    let mut rundown = Rundown::new(project.loaded.clone(), "Contract");
    for (id, entry) in entries {
        rundown.entries.insert(id.clone(), entry.clone());
        rundown.order.push(id.clone());
    }
    rundown.recompute();
    project.rundowns.insert(project.loaded.clone(), rundown);
    project
}

fn call(name: &str, args: Value) -> Value {
    json!({ "fn": name, "args": args })
}

/// The service call upstream makes for an action, and the message it fails
/// with when that call reports nothing happened.
fn described(
    project: &Project,
    action: Action,
) -> Result<(Vec<Value>, Option<String>), IntegrationError> {
    let runtime = |name: &str, args: Value| vec![call(&format!("runtimeService.{name}"), args)];
    Ok(match action {
        Action::Version => (vec![], None),
        Action::Poll => (vec![call("eventStore.poll", json!([]))], None),
        Action::Change { id, fields } => {
            let mut patch = Map::from_iter([("id".to_string(), json!(id))]);
            patch.extend(change_patch(project, &id, &fields)?);
            (vec![call("editEntry", json!(["rundown", patch]))], None)
        }
        Action::Message(patch) => {
            let mut args = Map::new();
            if let Some(timer) = patch.timer {
                let mut fields = Map::new();
                if let Some(text) = timer.text {
                    fields.insert("text".into(), json!(text));
                }
                for (key, value) in [
                    ("visible", timer.visible),
                    ("blink", timer.blink),
                    ("blackout", timer.blackout),
                ] {
                    if let Some(value) = value {
                        fields.insert(key.into(), json!(value));
                    }
                }
                if let Some(source) = timer.secondary_source {
                    fields.insert("secondarySource".into(), json!(source));
                }
                args.insert("timer".into(), Value::Object(fields));
            }
            if let Some(secondary) = patch.secondary {
                args.insert("secondary".into(), json!(secondary));
            }
            (vec![call("messageService.patch", json!([args]))], None)
        }
        Action::Playback { command, failure } => {
            let calls = match command {
                Command::Start => runtime("start", json!([])),
                Command::StartNext => runtime("startNext", json!([])),
                Command::StartPrevious => runtime("startPrevious", json!([])),
                Command::StartId(id) => runtime("startById", json!([id])),
                Command::StartIndex(index) => runtime("startByIndex", json!([index])),
                Command::StartCue(cue) => runtime("startByCue", json!([cue])),
                Command::LoadNext => runtime("loadNext", json!([])),
                Command::LoadPrevious => runtime("loadPrevious", json!([])),
                Command::LoadId(id) => runtime("loadById", json!([id])),
                Command::LoadIndex(index) => runtime("loadByIndex", json!([index])),
                Command::LoadCue(cue) => runtime("loadByCue", json!([cue])),
                Command::Pause => runtime("pause", json!([])),
                Command::Stop => runtime("stop", json!([])),
                Command::Reload => runtime("reload", json!([])),
                Command::Roll => runtime("roll", json!([])),
                Command::AddTime(ms) => runtime("addTime", json!([ms])),
                Command::SetOffsetMode(mode) => runtime("setOffsetMode", json!([mode])),
            };
            (calls, failure)
        }
        Action::AuxTimer { index, command } => {
            let aux =
                |name: &str, args: Value| vec![call(&format!("auxTimerService.{name}"), args)];
            let calls = match command {
                AuxCommand::Start => aux("start", json!([index])),
                AuxCommand::Pause => aux("pause", json!([index])),
                AuxCommand::Stop => aux("stop", json!([index])),
                AuxCommand::SetTime(ms) => aux("setTime", json!([ms, index])),
                AuxCommand::AddTime(ms) => aux("addTime", json!([ms, index])),
                AuxCommand::Direction(direction) => {
                    let direction = match direction {
                        SimpleDirection::CountUp => "count-up",
                        SimpleDirection::CountDown => "count-down",
                    };
                    aux("setDirection", json!([direction, index]))
                }
            };
            (calls, None)
        }
        Action::Client(command) => {
            let calls = match command {
                ClientCommand::Rename { target, name } => {
                    vec![call("socket.renameClient", json!([target, name]))]
                }
                ClientCommand::Redirect { target, path } => {
                    vec![call("socket.redirectClient", json!([target, path]))]
                }
                ClientCommand::Identify { target, identify } => {
                    vec![call("socket.identifyClient", json!([target, identify]))]
                }
            };
            (calls, None)
        }
        Action::Teleprompter(command) => (
            vec![call("handleTeleprompterCommand", json!([command]))],
            None,
        ),
        Action::Nothing => (vec![], None),
    })
}

/// Upstream's outcome, read off a case.
enum Upstream<'a> {
    Done(&'a [Value]),
    Refused {
        message: Option<&'a str>,
        calls: &'a [Value],
        ok: bool,
    },
}

/// Compares our handling of a request with upstream's; `None` when they agree.
fn mismatch(
    project: &Project,
    ours: Result<Action, IntegrationError>,
    upstream: Upstream,
) -> Option<String> {
    let ours = ours
        .and_then(|action| described(project, action))
        .map(|(calls, failure)| (calls.iter().map(normalised).collect::<Vec<_>>(), failure));
    match (upstream, ours) {
        (Upstream::Done(want), Ok((calls, _))) if calls == want => None,
        (Upstream::Done(want), other) => Some(format!("upstream {want:?}, ours {other:?}")),
        // refused before any service was asked: the same message
        (Upstream::Refused { message, .. }, Err(error)) => match message {
            Some(message) if message != error.message => Some(format!(
                "upstream refused with {message:?}, ours with {:?}",
                error.message
            )),
            _ => None,
        },
        // the service was asked and reported nothing happened
        (
            Upstream::Refused {
                message,
                calls: want,
                ok: false,
            },
            Ok((calls, failure)),
        ) if calls == want && failure.as_deref() == message => None,
        (Upstream::Refused { message, .. }, other) => {
            Some(format!("upstream refused with {message:?}, ours {other:?}"))
        }
    }
}

#[test]
fn http_requests_match_upstream() {
    let cases = fixture();
    let project = project(&cases);
    let mut failures = Vec::new();

    for case in &cases.http {
        if DELIBERATE.iter().any(|(name, _)| *name == case.name) {
            continue;
        }
        let path = case.path.strip_prefix("/api").unwrap();
        let (path, query) = match path.split_once('?') {
            Some((path, query)) => (path, Some(query)),
            None => (path, None),
        };
        let call = http_call(path, query);

        if case.status == 200 {
            if call != Ok(HttpCall::Hello) {
                failures.push(format!("{}: upstream greets, ours {call:?}", case.name));
            }
            continue;
        }
        let ours = call.and_then(|call| match call {
            HttpCall::Hello => Err(IntegrationError::new("hello")),
            HttpCall::Action { tag, payload } => parse(&tag, payload.as_ref()),
        });
        let upstream = match case.status {
            202 => Upstream::Done(&case.calls),
            _ => Upstream::Refused {
                // Express's own error page, for a path it cannot decode
                message: case.body.get("message").and_then(Value::as_str),
                calls: &case.calls,
                ok: case.ok,
            },
        };
        if let Some(problem) = mismatch(&project, ours, upstream) {
            failures.push(format!("{}: {problem}", case.name));
        }
    }

    assert!(
        failures.is_empty(),
        "{} of {} differ:\n{}",
        failures.len(),
        cases.http.len(),
        failures.join("\n")
    );
}

#[test]
fn websocket_packets_match_upstream() {
    let cases = fixture();
    let project = project(&cases);
    let mut failures = Vec::new();

    for case in &cases.ws {
        if DELIBERATE.iter().any(|(name, _)| *name == case.name) {
            continue;
        }
        let ours = parse(&case.tag, case.payload.as_ref());
        let upstream = match &case.error {
            None => Upstream::Done(&case.calls),
            Some(message) => Upstream::Refused {
                message: Some(message),
                calls: &case.calls,
                ok: case.ok,
            },
        };
        if let Some(problem) = mismatch(&project, ours, upstream) {
            failures.push(format!("{}: {problem}", case.name));
        }
    }

    assert!(
        failures.is_empty(),
        "{} of {} differ:\n{}",
        failures.len(),
        cases.ws.len(),
        failures.join("\n")
    );
}

#[test]
fn every_deliberate_difference_is_still_a_difference() {
    let cases = fixture();
    let token = cases
        .http
        .iter()
        .find(|case| case.name == DELIBERATE[0].0)
        .unwrap();
    assert_ne!(
        token.status, 202,
        "upstream now ignores ?token=; drop it from DELIBERATE"
    );
    let fraction = cases
        .ws
        .iter()
        .find(|case| case.name == DELIBERATE[1].0)
        .unwrap();
    assert_eq!(
        fraction.calls[0]["args"][0],
        json!(1500.4),
        "upstream now adds whole milliseconds; drop it from DELIBERATE"
    );
}
